body.usercss:

#EDITOR_AREA {
    height: calc(100% - 10px);
    width: calc(100% - 10px);
    padding: 5px;
    overflow: auto;
    border: 1px solid #f0f0f0;
}

userscript.function:

var target = formObj.getContainer("EDITOR_BOX");
target.innerHTML = '<div id="EDITOR_AREA"></div>'
editorResizeHandler();

isNoticePopup = SUX.getModuleTop().Sepoa.request.isPopup;

formObj.getForm('formObj_0').getVault('ATTACH_NO').changeMode('VI');

checkIsNoticePopup();

if (request.NOTICE_NUMBER) {
    doQuery(request.NOTICE_NUMBER);
}


if(typeof(isNoticePopup) != 'undefined' && isNoticePopup == 'true'){
    var fileCount = arguments[1].fileCount;
    if(fileCount == 0){
        formObj.hideItem("ATTACH_NO");
    } else {
        formObj.showItem("ATTACH_NO");
    }
}


if (noticeNumber) {
    $data.NOTICE_NUMBER = noticeNumber;
}
doServiceAjax('sepoa.svc.admin.AD_202_3', 'CONNECTION', 'doQuery', {
    NOTICE_NUMBER: noticeNumber
}, function(so) {
    if (so.status == 1) {
        var sf = new SepoaFormater(so.result[0]);
        renderData(sf, new SepoaFormater(so.result[1]))
    } else {
        Alert(so.message);
    }
});


if (state == 1) {
    if (name == 'FLAG') {
        var before = SUX.root.getCookie("sepoa.notice.ignore");

        if (before) {
            before = before.split(",");
        } else {
            before = [];
        }
        var noticeNumber = $data.NOTICE_NUMBER;
        if (state) {
            if (before.indexOf(noticeNumber) < 0) {
                before.push(noticeNumber);
                sUtils.cookie.set("sepoa.notice.ignore", before.join(','), 1);
            }
            if (SUX.pools.AD_202_1) {
                callFunction('AD_202_1', 'deleteCell', [Sepoa.request.NOTICE_NUMBER]);
            }
        } else {
            if (before.indexOf(noticeNumber) >= 0) {
                before.splice(before.indexOf(noticeNumber), 1);
                sUtils.cookie.set("sepoa.notice.ignore", before.join(','), 1);
            }
        }
    }
}


if (!sf) {
    sf = tempData;
    sf2 = tempContent;
} else {
    tempData = sf;
    tempContent = sf2;
}
if (!sf) return;
var c = '';
for (var i = 0; i < sf2.getRowCount(); i++) {
    c += sf2.getValue('CONTENT', i);
}
c = c.replaceAll("\\\"", "\"");
c = sUtils.string.decodeHTML(c);
if (!tempData) {
    clearForm();
} else {
    formObj.dataMapper(sf);
    formObj.getForm('formObj_0').getVault('ATTACH_NO').changeMode('VI');
    $('#EDITOR_AREA').html(c);
}

var cookieData = sUtils.cookie.get("sepoa.notice.ignore");
if (cookieData) {
    cookieData = cookieData.split(",");
} else {
    cookieData = [];
}
if (cookieData.indexOf(sf.getValue('NOTICE_NUMBER', 0)) >= 0) {
    formObj.setValue('FLAG', 1)
}


var target = formObj.getContainer("EDITOR_BOX");
var height = document.body.offsetHeight - dhx.absTop(formObj.getContainer("EDITOR_BOX")) - 10;
target.style.height = height + 'px';
